using DistributedMonolith.Products.Application; using DistributedMonolith.SharedContracts;
namespace DistributedMonolith.Products.Api;
public static class Endpoints{public static void MapProductEndpoints(this WebApplication app){var api=app.MapGroup("/api/products").WithTags("Products");api.MapPost("/",async(CreateProductRequest r,ProductService s)=>Results.Created("/api/products",await s.Create(r)));api.MapGet("/{id:guid}",async(Guid id,ProductService s)=>await s.Get(id)is{} p?Results.Ok(p):Results.NotFound());api.MapPut("/{id:guid}/stock",async(Guid id,UpdateStockRequest r,ProductService s)=>await s.UpdateStock(id,r.Quantity)is{} p?Results.Ok(p):Results.NotFound());app.MapPost("/internal/products/{id:guid}/reserve",async(Guid id,StockReservationRequest r,ProductService s)=>Results.Ok(await s.Reserve(id,r.Quantity))).ExcludeFromDescription();}}
